  'help.maze.fig2': 'Corridor width 2',
  'help.fig.notetext_1': 'One click places a line of plain text',
  'help.fig.notetext_2': 'The plate style displays text on a colored background',
  'help.fig.notetext_word1': 'Orchard',
  'help.fig.notetext_word2': 'Meet here',
  // Section figures of the share and agent groups: captions, and the mid-run fixture's strings.
  'help.save.entry_figcap': "Save and share is at the top right beside the menu. All exports described here begin there.",
  'help.share.import_figcap': "The Import map window, opened from the menu: drop a shared image or a JSON file here, or click to choose one.",
  'help.agentrun.oversight_figcap': "The oversight control on the settings card: three levels side by side, with the line beneath explaining the selected one.",
  'help.agentrun.steer_figcap': "A note sent during a task appears above the field and applies to the next step. The close control withdraws it.",
